var n=`0479-mujadara`;var o=`world-0479`;var t=`LB`;var r=`western-asia`;var a=4;var s=69;var l={en:`Mujadara`,ua:`Муджадара`};var d={en:`A traditional dish from Lebanon, centered on green lentils, yellow onion, white rice, parsley. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: зелена сочевиця, жовта цибуля, білий рис, петрушка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`green-lentils`,250,`g`],[`water`,900,`ml`]]},{en:`Slowly fry onion until deep brown and sweet, saving some crisp onions for the top.`,ua:`Повільно смажте цибулю до насиченого коричневого кольору й солодкуватості; частину хрусткої цибулі залиште для верху.`,t:[`chopping`,`sauteing`],m:15,i:[[`yellow-onion`,380,`g`],[`extra-virgin-olive-oil`,80,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`white-rice`,210,`g`],[`ground-cumin`,5,`g`],[`water`,400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,25,`g`]]}];var u={slug:n,id:o,country:`LB`,region:r,servings:4,minutes:69,title:l,text:d,steps:g};export{t as country,u as default,o as id,s as minutes,r as region,a as servings,n as slug,g as steps,d as text,l as title};